(()=>{
  'use strict';
  const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
  const STORE='jornada-smart-notebook-v78';
  const MAX_SOURCES=5;
  let smart=load(),busy=false;
  function load(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return{}}}
  function persist(){localStorage.setItem(STORE,JSON.stringify(smart))}
  function campaignKey(){return state?.activeCampaignId||'default'}
  function current(){const key=campaignKey();return smart[key]||(smart[key]={subject:'all',sources:[],cache:{},lastResult:null,manualEmpty:false})}
  function safe(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function hash(value){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36)}
  function readySources(){return(cloudDocuments||[]).filter(doc=>doc.document_type!=='edital'&&doc.processing_status==='ready'&&(ALL_SUMMARIES||[]).some(summary=>summary.documentId===doc.id))}
  function sourceSubject(doc){const own=(ALL_SUMMARIES||[]).find(summary=>summary.documentId===doc.id)?.category;return canonicalSubjectName(own||doc.detected_subject||doc.metadata?.primary_subject||'Conteúdo geral')}
  function subjectSources(){const data=current(),sources=readySources();return data.subject==='all'?sources:sources.filter(doc=>subjectKey(sourceSubject(doc))===subjectKey(data.subject))}
  function selectedSources(){const available=subjectSources(),chosen=new Set(current().sources);return available.filter(doc=>chosen.has(doc.id))}
  function ensureSelection(){const data=current(),available=subjectSources();data.sources=data.sources.filter(id=>available.some(doc=>doc.id===id)).slice(0,MAX_SOURCES);if(!data.sources.length&&available.length&&!data.manualEmpty)data.sources=available.slice(0,MAX_SOURCES).map(doc=>doc.id);persist()}
  function selectedSummaries(){const ids=new Set(selectedSources().map(doc=>doc.id));return(ALL_SUMMARIES||[]).filter(summary=>ids.has(summary.documentId))}
  function contextBlock(){const summaries=selectedSummaries(),parts=summaries.map(item=>[`[FONTE: ${item.source||'PDF'}${item.pageStart?` | PÁGINAS: ${item.pageStart}${item.pageEnd>item.pageStart?`-${item.pageEnd}`:''}`:''}]`,`DISCIPLINA: ${item.category}`,`ASSUNTO: ${item.title}`,item.explanation,(item.points||[]).length?`PONTOS: ${item.points.join('; ')}`:'',item.example?`EXEMPLO: ${item.example}`:'',item.bizu?`BIZU: ${item.bizu}`:'',item.mnemonic?`MNEMÔNICO: ${item.mnemonic}`:'',item.trap?`PEGADINHA: ${item.trap}`:''].filter(Boolean).join('\n'));return parts.join('\n\n').slice(0,22000)}
  function sourceSignature(){return selectedSources().map(doc=>`${doc.id}:${doc.updated_at||doc.created_at||''}`).sort().join('|')}

  function install(){
    const tabs=q('#study .studyTabs'),notebook=q('#notebook');if(!tabs||!notebook||q('[data-study="smart"]'))return;
    tabs.classList.add('smartEnabled');tabs.insertAdjacentHTML('beforeend','<button class="studyTab" data-study="smart">Caderno IA</button>');
    notebook.insertAdjacentHTML('afterend',`<div class="studyPanel" id="smart"><div class="smartNotebook"><div class="card smartHero"><div class="eyebrow">CADERNO INTELIGENTE</div><h2>Estude somente pelas fontes escolhidas</h2><p class="muted">Selecione os PDFs, gere um guia ou converse com o Tutor. As respostas pedem citações de fonte e página.</p><div class="smartGuard"><span class="tag">Sem áudio</span><span class="tag">Sem mapa mental</span><span class="tag">Quiz sem consumir IA</span><span class="tag">Cache contra chamadas repetidas</span></div></div><div class="smartLayout"><aside class="card smartSources"><div class="sectionHead"><h2>Fontes</h2><span class="tag" id="smartSourceCount">0/0</span></div><label class="field">Disciplina<select id="smartSubject"></select></label><div class="smartSelectActions"><button class="ghost" id="smartSelectAll">Marcar todas</button><button class="ghost" id="smartSelectNone">Limpar</button></div><div class="smartSourcesList" id="smartSourcesList"></div><div class="smartEstimate" id="smartEstimate"></div></aside><section class="smartWorkspace"><div class="card"><div class="sectionHead"><div><h2>Ferramentas</h2><p class="small muted" style="margin:3px 0 0">A IA só será chamada depois da sua confirmação.</p></div><span class="tag" id="smartProvider">DeepSeek → Groq → Gemini</span></div><div class="smartActions"><button class="smartAction" id="smartGuide"><b>Gerar guia de estudo</b><span>1 chamada; reutiliza o cache</span></button><button class="smartAction" id="smartQuiz"><b>Iniciar quiz adaptativo</b><span class="smartNoCredit">Não consome IA</span></button></div><label class="field">Pergunte ao Tutor</label><div class="smartQuestion"><textarea id="smartQuestion" placeholder="Ex.: Explique a diferença entre direitos individuais e sociais usando somente as fontes marcadas."></textarea><button class="action" id="smartAsk">Perguntar</button></div><p class="small muted" id="smartMessage">Selecione ao menos uma fonte.</p><div id="smartResult"></div></div><div class="card"><div class="sectionHead"><h2>Cobertura e lacunas</h2><span class="tag">Edital × materiais</span></div><div class="smartCoverageGrid" id="smartCoverage"></div><div class="gapList" id="smartGaps"></div></div></section></div></div></div>`);
    qa('[data-study]').forEach(button=>button.onclick=()=>{qa('.studyTab').forEach(item=>item.classList.toggle('active',item===button));qa('.studyPanel').forEach(panel=>panel.classList.toggle('active',panel.id===button.dataset.study));if(button.dataset.study==='smart')renderSmart()});
    q('#smartSubject').onchange=event=>{current().subject=event.target.value;current().sources=[];current().manualEmpty=false;current().lastResult=null;ensureSelection();renderSmart()};
    q('#smartSelectAll').onclick=()=>{current().sources=subjectSources().slice(0,MAX_SOURCES).map(doc=>doc.id);current().manualEmpty=false;current().lastResult=null;persist();renderSmart();if(subjectSources().length>MAX_SOURCES)toast(`Para economizar créditos, selecione até ${MAX_SOURCES} fontes por consulta.`)};
    q('#smartSelectNone').onclick=()=>{current().sources=[];current().manualEmpty=true;current().lastResult=null;persist();renderSmart()};
    q('#smartSourcesList').onchange=event=>{if(!event.target.matches('[data-smart-source]'))return;const ids=new Set(current().sources),id=event.target.dataset.smartSource;if(event.target.checked&&ids.size>=MAX_SOURCES){event.target.checked=false;return toast(`Selecione no máximo ${MAX_SOURCES} fontes por consulta para controlar o consumo.`)}event.target.checked?ids.add(id):ids.delete(id);current().sources=[...ids];current().manualEmpty=current().sources.length===0;current().lastResult=null;persist();renderSmart()};
    q('#smartGuide').onclick=()=>runGeneration('guide');q('#smartAsk').onclick=()=>runGeneration('tutor');q('#smartQuiz').onclick=startAdaptiveQuiz;
  }

  function renderSmart(){
    if(!q('#smart'))return;const data=current(),subjects=[...new Set(readySources().map(sourceSubject))].sort((a,b)=>a.localeCompare(b,'pt-BR')),select=q('#smartSubject');select.innerHTML='<option value="all">Todas as disciplinas</option>'+subjects.map(subject=>`<option value="${safe(subject)}">${safe(subject)}</option>`).join('');select.value=subjects.some(subject=>subjectKey(subject)===subjectKey(data.subject))?subjects.find(subject=>subjectKey(subject)===subjectKey(data.subject)):'all';if(select.value!==data.subject)data.subject=select.value;ensureSelection();const sources=subjectSources(),chosen=new Set(data.sources);q('#smartSourceCount').textContent=`${sources.filter(doc=>chosen.has(doc.id)).length}/${sources.length}`;q('#smartSourcesList').innerHTML=sources.length?sources.map(doc=>{const count=ALL_SUMMARIES.filter(summary=>summary.documentId===doc.id).length,coverage=Number(doc.metadata?.coverage?.percent)||0;return`<label class="smartSource"><input type="checkbox" data-smart-source="${safe(doc.id)}" ${chosen.has(doc.id)?'checked':''}><span><b>${safe(doc.title)}</b><span>${safe(sourceSubject(doc))} · ${count} assunto${count===1?'':'s'}${coverage?` · ${coverage}% coberto`:''}</span></span></label>`}).join(''):'<div class="empty">Nenhum material processado nesta disciplina.</div>';const context=contextBlock(),selected=selectedSources(),personalStatus=window.getPersonalAiStatus?.();if(q('#smartProvider'))q('#smartProvider').textContent=personalStatus?.configured?`✓ Gemini pessoal (••••${personalStatus.last_four||''})`:'DeepSeek → Groq → Gemini';q('#smartEstimate').innerHTML=selected.length?`<strong>${selected.length}/${MAX_SOURCES} fontes</strong> · ${selectedSummaries().length} assuntos · contexto limitado a ${Math.ceil(context.length/1000)} mil caracteres.<br>Guia/Tutor: 1 chamada. Quiz: nenhuma chamada.`:'Marque ao menos uma fonte para utilizar o Caderno Inteligente.';q('#smartGuide').disabled=!selected.length||busy;q('#smartAsk').disabled=!selected.length||busy;q('#smartQuiz').disabled=!(ALL_QUESTIONS||[]).some(item=>data.subject==='all'||subjectKey(item.subject)===subjectKey(data.subject));renderCoverage();renderResult()}

  function renderCoverage(){
    const summaries=selectedSummaries(),sources=selectedSources(),questions=(ALL_QUESTIONS||[]).filter(item=>current().subject==='all'||subjectKey(item.subject)===subjectKey(current().subject)),missions=(missionPool?.()||[]).filter(item=>current().subject==='all'||subjectKey(item.subject)===subjectKey(current().subject)),covered=missions.filter(mission=>summaries.some(summary=>subjectKey(summary.category)===subjectKey(mission.subject)&&normalizeText([summary.title,summary.explanation,...(summary.points||[])].join(' ')).includes(normalizeText(mission.name).slice(0,28)))),percent=missions.length?Math.round(covered.length/missions.length*100):0;q('#smartCoverage').innerHTML=`<div class="smartMetric"><b>${sources.length}</b><span>fontes selecionadas</span></div><div class="smartMetric"><b>${summaries.length}</b><span>assuntos resumidos</span></div><div class="smartMetric"><b>${questions.length}</b><span>questões disponíveis</span></div><div class="smartMetric"><b>${percent}%</b><span>tópicos relacionados</span></div><div class="smartMetric"><b>${missions.length}</b><span>itens do edital</span></div><div class="smartMetric"><b>${missions.length-covered.length}</b><span>lacunas estimadas</span></div>`;const bySubject={};for(const mission of missions){const key=mission.subject||'Edital';bySubject[key]??={total:0,summary:0,questions:0};bySubject[key].total++}for(const summary of summaries){const key=Object.keys(bySubject).find(name=>subjectKey(name)===subjectKey(summary.category));if(key)bySubject[key].summary++}for(const question of questions){const key=Object.keys(bySubject).find(name=>subjectKey(name)===subjectKey(question.subject));if(key)bySubject[key].questions++}const rows=Object.entries(bySubject).sort((a,b)=>(a[1].summary+a[1].questions)-(b[1].summary+b[1].questions)).slice(0,8);q('#smartGaps').innerHTML=rows.length?rows.map(([name,value])=>`<div class="gapItem ${value.summary&&value.questions?'good':''}"><b>${safe(name)}</b><div class="small">${value.total} tópico${value.total===1?'':'s'} no edital · ${value.summary} resumo${value.summary===1?'':'s'} · ${value.questions} questão${value.questions===1?'':'ões'}</div></div>`).join(''):'<div class="empty">Insira e analise um edital para comparar as fontes com o conteúdo programático.</div>'}

  function promptFor(type,question){const citation='Use exclusivamente o MATERIAL DE REFERÊNCIA. Ao final de cada seção, cite no formato [Fonte: nome do arquivo, pág. X]. Se a página não estiver informada, use [Fonte: nome do arquivo]. Não invente páginas, artigos ou informações ausentes.';if(type==='guide')return`${citation}\nCrie um guia de estudo pedagógico com: visão geral, pré-requisitos, ordem recomendada, pontos essenciais, exemplos, pegadinhas, checklist e plano de revisão 1-7-30 dias. Não produza mapa mental nem roteiro de áudio.`;return`${citation}\nAtue como tutor socrático, mas responda de forma útil à pergunta. Explique passo a passo, faça uma pergunta de verificação ao final e indique o trecho que o estudante deve revisar.\nPergunta: ${question}`}
  async function runGeneration(type){
    if(busy)return;const question=q('#smartQuestion').value.trim();if(type==='tutor'&&question.length<3)return toast('Escreva sua pergunta para o Tutor.');const context=contextBlock();if(!context)return toast('Selecione ao menos uma fonte processada.');const cacheKey=hash(`${type}|${sourceSignature()}|${type==='tutor'?question:''}`),cached=current().cache[cacheKey];if(cached){current().lastResult=cached;persist();renderResult();toast('Resultado recuperado do cache sem consumir nova chamada.');return}const confirmed=confirm(`Esta ação usará 1 pergunta da cota diária do assistente.\n\nFontes: ${selectedSources().length}\nAssuntos: ${selectedSummaries().length}\n\nDeseja continuar?`);if(!confirmed)return;busy=true;renderSmart();q('#smartMessage').textContent='Preparando resposta fundamentada nas fontes...';try{const session=await validSession();if(!session)throw new Error('Entre novamente para utilizar o Caderno Inteligente.');const response=await fetch(`${SUPABASE_URL}/functions/v1/assistente-pmpe`,{method:'POST',headers:authHeaders(session.access_token),body:JSON.stringify({question:promptFor(type,question),context,mode:type==='guide'?'guia de estudo fundamentado':'tutor fundamentado',campaign_id:activeCampaign()?.dbId,campaign:activeCampaign()?.name,document_titles:selectedSources().map(doc=>doc.title)})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`Erro ${response.status} ao consultar o assistente.`);const providerLabel=result.provider==='gemini'&&result.key_source==='personal'?'Gemini (chave pessoal)':(result.provider||'IA');const item={type,question:type==='guide'?'Guia de estudo':question,answer:result.answer,provider:providerLabel,sources:selectedSources().map(doc=>doc.title),createdAt:new Date().toISOString()};current().cache[cacheKey]=item;current().lastResult=item;persist();renderResult();q('#smartMessage').textContent='Resposta concluída e guardada no cache.'}catch(error){q('#smartMessage').textContent=error.message;toast(error.message)}finally{busy=false;renderSmart()}}
  function renderResult(){const root=q('#smartResult'),item=current().lastResult;if(!root)return;if(!item){root.innerHTML='';return}root.innerHTML=`<article class="smartResult"><div class="smartResultHead"><div><b>${safe(item.question)}</b><div class="smartResultMeta">${safe(item.provider)} · ${new Date(item.createdAt).toLocaleString('pt-BR')} · ${item.sources.length} fonte${item.sources.length===1?'':'s'}</div></div><button class="ghost" id="smartClearResult">Fechar</button></div><div class="smartResultBody aiAnswer">${formatAIAnswer(item.answer)}</div></article>`;q('#smartClearResult').onclick=()=>{current().lastResult=null;persist();renderResult()}}
  function startAdaptiveQuiz(){const subject=current().subject,scores=(state.scores||[]).filter(item=>subject==='all'||subjectKey(item.subject)===subjectKey(subject)),total=scores.reduce((sum,item)=>sum+Number(item.total||0),0),correct=scores.reduce((sum,item)=>sum+Number(item.correct||0),0),rate=total?correct/total:0,target=rate>=.8?'dificil':rate>=.6?'medio':'facil';let pool=questionsForMode('battle',subject).filter(item=>{const raw=normalizeText(item.difficulty||'medio');return target==='facil'?raw.startsWith('fac'):target==='dificil'?raw.startsWith('dif'):raw.startsWith('med')});if(pool.length<3)pool=questionsForMode('battle',subject);if(!pool.length)return toast('Ainda não existem questões para esta seleção.');activeQuestions={mode:'battle',subject,questions:balancedQuestions(pool,Math.min(5,pool.length)).map(prepareQuestion),current:0,correct:0,answered:false};q('#questionDialogTitle').textContent=`Quiz adaptativo · ${target==='facil'?'fácil':target==='dificil'?'difícil':'médio'}`;q('#questionDialog').showModal();showQuestion()}

  install();renderSmart();
  const baseRender=render;render=function(){baseRender();renderSmart()};
  const baseLoadGenerated=loadGeneratedContent;loadGeneratedContent=async function(){const result=await baseLoadGenerated();renderSmart();return result};
  q('#aboutDialog .tag')&&(q('#aboutDialog .tag').textContent='Versão 78 · Caderno Inteligente com fontes');
  q('#diagnosticsDialog .small.muted')&&(q('#diagnosticsDialog .small.muted').textContent='Versão 78 · fontes, citações, questões, IA, PDFs e sincronização');
})();
